import sys, json, random, collections
sys.path.insert(0,'/workspace/site'); sys.path.insert(0,'/tmp/ref'); sys.path.insert(0,'/workspace/submission')
import reference, gen, gen3, gen2
from pipeline import execute, build_release
stats = collections.Counter(); bad = 0
def entries_of(releases, capacity):
    return {spec['id']: build_release(spec, capacity)[0].entries for spec in releases}
gens = [gen.gen_request, gen3.gen_request, lambda r: gen2.gen_request(r, entries_of)]
for seed in (201, 202, 203, 204, 205, 206, 207, 208):
    rng = random.Random(seed)
    for trial in range(120):
        req = gens[rng.randrange(3)](rng)
        payload = json.dumps(req, separators=(',',':'))
        try:
            exp = reference.run(json.loads(payload))
        except RuntimeError:
            exp = None
        except ValueError:
            stats['ref_invalid'] += 1
            try:
                got = execute(json.loads(payload))
                if 'error' not in got: print('MISMATCH reject', seed, trial); bad += 1
            except ValueError: pass
            continue
        try:
            got = execute(json.loads(payload))
        except ValueError:
            got = {'error': 'x'}
        if exp is not None and got != exp:
            bad += 1; print('MISMATCH seed', seed, 'trial', trial)
            open('/tmp/fail.json','w').write(json.dumps(req,indent=1)); break
        if exp is None: stats['skipped'] += 1; continue
        stats['cases'] += 1
        for c in got['catalog']:
            stats['noncore'] += sum(1 for cl in c['clusters'] if len(cl['members'])>len(cl['core']))
            stats['kept'] += len(c['priority']); stats['clusters'] += len(c['clusters'])
        for d in got['decisions']: stats['reason_'+d['reason']] += 1
        for i in got['installs']: stats['install_'+i['status']] += 1
print(dict(stats), 'bad', bad)
